def fetch_font(font_name):
    """
    Retrieves embeddable font resource from given ``font_name``.

    For now only local fonts are supported.

    :param str font_name: name of font to fetch
    :returns: path to local font file.
    :rtype: str
    :raises: :exc:`~easy_pdf.exceptions.UnsupportedFontException`
    """
    # TODO: support for remote fonts
    if font_name.startswith("http"):
        raise UnsupportedFontException(font_name)

    if not font_name.startswith("/"):
        font_name = "/" + font_name

    return os.path.abspath(
        os.path.join(os.path.dirname(__file__), "resources/fonts", font_name)
    )


